create or replace function public.capture_udu_audit() returns trigger language plpgsql security definer set search_path=public as $$ declare v_actor uuid;v_actor_name text;v_old jsonb;v_new jsonb;v_id text;begin v_actor:=auth.uid();select full_name into v_actor_name from public.profiles where id=v_actor;if tg_op='DELETE' then v_old:=to_jsonb(old);v_new:=null;v_id:=coalesce(v_old->>'id',v_old->>'item_id',v_old->>'addition_code');elsif tg_op='UPDATE' then v_old:=to_jsonb(old);v_new:=to_jsonb(new);v_id:=coalesce(v_new->>'id',v_new->>'item_id',v_new->>'addition_code');else v_old:=null;v_new:=to_jsonb(new);v_id:=coalesce(v_new->>'id',v_new->>'item_id',v_new->>'addition_code');end if;insert into public.audit_logs(actor_id,action,entity_type,entity_id,details) values(v_actor,'ROW_'||tg_op,tg_table_name,v_id,jsonb_build_object('actor_name',coalesce(v_actor_name,'Unknown / system'),'before',v_old,'after',v_new,'table',tg_table_name,'db_user',session_user));if tg_op='DELETE' then return old;else return new;end if;end $$;
create or replace function public.sync_item_schedule_actuals() returns trigger language plpgsql set search_path=public as $$ begin insert into public.item_schedules(item_id,actual_last_receipt_at,actual_last_use_at,updated_by,updated_at) values(new.item_id,case when new.transaction_type in ('MASUK','PENYESUAIAN_MASUK') then new.occurred_at else null end,case when new.transaction_type in ('KELUAR','PENYESUAIAN_KELUAR') then new.occurred_at else null end,new.created_by,now()) on conflict(item_id) do update set actual_last_receipt_at=case when new.transaction_type in ('MASUK','PENYESUAIAN_MASUK') then greatest(coalesce(public.item_schedules.actual_last_receipt_at,new.occurred_at),new.occurred_at) else public.item_schedules.actual_last_receipt_at end,actual_last_use_at=case when new.transaction_type in ('KELUAR','PENYESUAIAN_KELUAR') then greatest(coalesce(public.item_schedules.actual_last_use_at,new.occurred_at),new.occurred_at) else public.item_schedules.actual_last_use_at end,updated_by=new.created_by,updated_at=now();return new;end $$;
revoke all on function public.capture_udu_audit() from public,anon,authenticated;revoke all on function public.sync_item_schedule_actuals() from public,anon,authenticated;revoke all on function public.enforce_boq_addition_rules() from public,anon,authenticated;